// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.GenericPlanNode;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailQuery;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * The Workbench Types page issues two fixed queries ({@code TypesServlet}) and asks for the LMDB result cache. Both
 * must be routed to the run/metadata specialists in AUTO mode: the count query is a one-pattern GROUP BY whose exact
 * answer is a few run headers, and the row-enumerating aggregate kernels are hundreds of times slower on real stores.
 * The Named Graphs page count ({@code ContextsServlet}) must likewise stay on the adjacency census.
 */
class LmdbWorkbenchTypesPageRoutingTest {

	private static final String NS = "http://example.com/types/";
	private static final String TYPES_DISTINCT = "SELECT DISTINCT ?type WHERE { ?subj a ?type }";
	private static final String TYPES_COUNTS = "SELECT ?type (COUNT(DISTINCT ?s) AS ?instances) "
			+ "WHERE { ?s a ?type } GROUP BY ?type";
	private static final String GRAPH_COUNTS = "SELECT ?context (COUNT(*) AS ?statements) "
			+ "WHERE { GRAPH ?context { ?s ?p ?o } } GROUP BY ?context";
	private static final int SUBJECTS = 300;
	private static final int CLASSES = 5;

	@TempDir
	Path directory;

	@ParameterizedTest(name = "adjacency={0}")
	@ValueSource(booleans = { true, false })
	void typesPageQueriesRouteToRunSpecialists(boolean adjacency) throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("store").toFile(), new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			Map<String, Long> expected = load(repository);
			if (adjacency) {
				assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS))
						.as(store.getDirectAdjacencyReadinessDescription())
						.isTrue();
			}
			try (RepositoryConnection connection = repository.getConnection()) {
				Map<String, Long> counts = new LinkedHashMap<>();
				GenericPlanNode countsPlan = run(connection, TYPES_COUNTS,
						row -> counts.put(row.getValue("type").stringValue(),
								Long.parseLong(row.getValue("instances").stringValue())));
				assertThat(counts).containsExactlyInAnyOrderEntriesOf(expected);
				assertThat(findMetric(countsPlan, "nativeExecutionPath"))
						.as("Types counts must use the run/metadata specialist:%n%s", countsPlan)
						.isEqualTo(adjacency ? "adjacencyAggregate" : "prefixRunGroups");

				Map<String, Long> listed = new LinkedHashMap<>();
				GenericPlanNode listPlan = run(connection, TYPES_DISTINCT,
						row -> listed.put(row.getValue("type").stringValue(), 1L));
				assertThat(listed.keySet()).containsExactlyInAnyOrderElementsOf(expected.keySet());
				assertThat(findMetric(listPlan, "nativeExecutionPath"))
						.as("Types list must use prefix runs:%n%s", listPlan)
						.contains("prefixRun")
						.doesNotContain("irKernel");
			}
		} finally {
			repository.shutDown();
		}
	}

	/**
	 * The Named Graphs page count: a wildcard pattern grouped by context. With adjacency the census answers it from
	 * page headers; it must not lose the cold dispatch to a plane sweep that decodes every statement.
	 */
	@org.junit.jupiter.api.Test
	void namedGraphsCountRoutesToTheCensus() throws Exception {
		LmdbStore store = new LmdbStore(directory.resolve("graphs").toFile(), new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			load(repository);
			assertThat(AdjacencyEngagementTestAccess.buildNow(store))
					.as(store.getDirectAdjacencyReadinessDescription())
					.isTrue();
			try (RepositoryConnection connection = repository.getConnection()) {
				Map<String, Long> counts = new LinkedHashMap<>();
				GenericPlanNode plan = run(connection, GRAPH_COUNTS,
						row -> counts.put(row.getValue("context").stringValue(),
								Long.parseLong(row.getValue("statements").stringValue())));
				assertThat(counts).containsExactlyInAnyOrderEntriesOf(Map.of(NS + "g1", 200L, NS + "g2", 100L));
				assertThat(findMetric(plan, "nativeExecutionPath"))
						.as("Named Graphs counts must use the page-header census:%n%s", plan)
						.isEqualTo("adjacencyCensus");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static Map<String, Long> load(SailRepository repository) {
		ValueFactory vf = repository.getValueFactory();
		IRI[] types = new IRI[CLASSES];
		for (int i = 0; i < CLASSES; i++) {
			types[i] = vf.createIRI(NS, "Class" + i);
		}
		IRI name = vf.createIRI(NS, "name");
		IRI graph = vf.createIRI(NS, "g1");
		IRI second = vf.createIRI(NS, "g2");
		Map<String, Long> expected = new LinkedHashMap<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int i = 0; i < SUBJECTS; i++) {
				IRI subject = vf.createIRI(NS, "s" + i);
				IRI type = types[i % CLASSES];
				connection.add(subject, RDF.TYPE, type);
				expected.merge(type.stringValue(), 1L, Long::sum);
				if (i % 3 == 0) {
					// a second type for the same subject, in a named graph, and the same (subject, type) twice
					IRI other = types[(i + 1) % CLASSES];
					connection.add(subject, RDF.TYPE, other, graph);
					connection.add(subject, RDF.TYPE, type, graph);
					expected.merge(other.stringValue(), 1L, Long::sum);
				}
				connection.add(subject, name, vf.createLiteral("subject " + i),
						i % 3 == 0 ? second : (IRI) null);
			}
			connection.commit();
		}
		return expected;
	}

	private static GenericPlanNode run(RepositoryConnection connection, String query,
			java.util.function.Consumer<org.eclipse.rdf4j.query.BindingSet> consumer) {
		TupleQuery tupleQuery = connection.prepareTupleQuery(query);
		((SailQuery) tupleQuery).setLmdbResultCacheRequested(true);
		try (var rows = tupleQuery.evaluate()) {
			rows.forEach(consumer);
		}
		return tupleQuery.explain(Explanation.Level.Telemetry).toGenericPlanNode();
	}

	private static String findMetric(GenericPlanNode node, String metric) {
		String value = node.getStringMetricActual(metric);
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findMetric(child, metric);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}
}
